solution.solution.cpp:
#include <algorithm>
#include <cstdlib>
#include <functional>
#include <limits>
#include <queue>
#include <string>
#include <tuple>
#include <utility>
#include <vector>

struct SearchResult
{
    long long cost;
    int expanded;
    std::vector<std::pair<int, int>> path;
};

static int enterCost(char c) { return (c >= '1' && c <= '9') ? c - '0' : 1; }

static SearchResult search(const std::vector<std::string>& grid, bool heuristic)
{
    int rows = static_cast<int>(grid.size()), cols = rows ? static_cast<int>(grid[0].size()) : 0;
    int start = -1, goal = -1;
    for (int r = 0; r < rows; ++r)
        for (int c = 0; c < cols; ++c)
        {
            if (grid[r][c] == 'S') start = r * cols + c;
            if (grid[r][c] == 'G') goal = r * cols + c;
        }
    if (start < 0 || goal < 0) return { -1, 0, {} };
    int gr = goal / cols, gc = goal % cols;
    auto h = [&](int cell) { return heuristic ? std::abs(cell / cols - gr) + std::abs(cell % cols - gc) : 0LL; };

    const long long INF = std::numeric_limits<long long>::max();
    std::vector<long long> g(rows * cols, INF);
    std::vector<int> parent(rows * cols, -1);
    using Item = std::tuple<long long, long long, int>;               // (f, -g, cell)
    std::priority_queue<Item, std::vector<Item>, std::greater<Item>> open;
    g[start] = 0;
    open.push({ h(start), 0, start });
    int expanded = 0;
    const int dr[] = { -1, 1, 0, 0 }, dc[] = { 0, 0, -1, 1 };
    while (!open.empty())
    {
        auto [f, negG, cell] = open.top();
        open.pop();
        if (-negG > g[cell]) continue;
        ++expanded;
        if (cell == goal)
        {
            std::vector<std::pair<int, int>> path;
            for (int v = goal; v != -1; v = parent[v]) path.push_back({ v / cols, v % cols });
            std::reverse(path.begin(), path.end());
            return { g[goal], expanded, path };
        }
        int r = cell / cols, c = cell % cols;
        for (int d = 0; d < 4; ++d)
        {
            int nr = r + dr[d], nc = c + dc[d];
            if (nr < 0 || nr >= rows || nc < 0 || nc >= cols || grid[nr][nc] == '#') continue;
            int next = nr * cols + nc;
            long long cost = g[cell] + enterCost(grid[nr][nc]);
            if (cost < g[next])
            {
                g[next] = cost;
                parent[next] = cell;
                open.push({ cost + h(next), -cost, next });
            }
        }
    }
    return { -1, expanded, {} };
}

SearchResult dijkstraGrid(const std::vector<std::string>& grid) { return search(grid, false); }
SearchResult astarGrid(const std::vector<std::string>& grid) { return search(grid, true); }

unitTests:
#include <cstdlib>

static bool validPath(const std::vector<std::string>& grid, const SearchResult& r)
{
    if (r.path.empty()) return false;
    if (grid[r.path.front().first][r.path.front().second] != 'S' || grid[r.path.back().first][r.path.back().second] != 'G') return false;
    long long cost = 0;
    for (std::size_t i = 1; i < r.path.size(); ++i)
    {
        auto [a, b] = r.path[i - 1];
        auto [c, d] = r.path[i];
        if (std::abs(a - c) + std::abs(b - d) != 1) return false;
        char cell = grid[c][d];
        if (cell == '#') return false;
        cost += (cell >= '1' && cell <= '9') ? cell - '0' : 1;
    }
    return cost == r.cost;
}

TEST("small maps") {
    std::vector<std::string> m{ "S.9.", ".#9.", "...G" };
    auto d = dijkstraGrid(m), a = astarGrid(m);
    CHECK_EQ(d.cost, 5LL);
    CHECK_EQ(a.cost, 5LL);
    CHECK(validPath(m, d));
    CHECK(validPath(m, a));
    std::vector<std::string> swamp{ "S9G", ".#.", "..." };
    CHECK_EQ(astarGrid(swamp).cost, 6LL);                   // around the 9 (six steps) beats through it (9 + 1)
    CHECK_EQ(astarGrid({ "S#G" }).cost, -1LL);
    CHECK(astarGrid({ "S#G" }).path.empty());
    CHECK_EQ(astarGrid({ "SG" }).cost, 1LL);
}
TEST("A* agrees with Dijkstra on weighted maps") {
    std::vector<std::string> m(60, std::string(80, '.'));
    unsigned x = 12345;
    for (auto& row : m)
        for (char& c : row)
        {
            x = x * 1103515245 + 12345;
            unsigned k = (x >> 16) % 10;
            c = k < 2 ? '#' : k < 4 ? static_cast<char>('1' + (x >> 8) % 9) : '.';
        }
    m[0][0] = 'S';
    m[59][79] = 'G';
    auto d = dijkstraGrid(m), a = astarGrid(m);
    CHECK_EQ(a.cost, d.cost);
    if (d.cost >= 0) { CHECK(validPath(m, d)); CHECK(validPath(m, a)); }
    CHECK(a.expanded <= d.expanded);
}
TEST("A* expands far fewer cells on an open map") {
    std::vector<std::string> m(200, std::string(200, '.'));
    m[100][0] = 'S';
    m[100][199] = 'G';
    auto d = dijkstraGrid(m), a = astarGrid(m);
    CHECK_EQ(d.cost, 199LL);
    CHECK_EQ(a.cost, 199LL);
    CHECK(a.expanded < 1000);
    CHECK(d.expanded > 20000);
    CHECK(validPath(m, a));
}

